`timescale 1ns/1ps
/* Smoke/exact protocol bench for the non-production tile pipeline.  The
 * zero PW/DW multipliers make the expected int8 result exactly zero while
 * still exercising every DW token, scratch write, PW K read, and writeback. */
module tb_ds_word_window_dw_pw_tile_pipeline;
  localparam integer AW=24, WW=16, EW=4, TW=8;
  localparam [23:0] BASE0=24'h100000, BASE1=24'h200000;
  reg clk=0,rst_n=0; always #1 clk=~clk;
  reg fsv=0,fsb=0; reg [3:0] fse=0; reg [23:0] fba=0; reg [15:0] fwc=400; wire fsr,fdv,fdb; wire [3:0] fde;
  wire mrv; reg mrr=1; wire [23:0] mra; reg mspv=0; reg [31:0] msd=0;
  reg cv=0; wire cready; reg [3:0] cti=0; reg signed [127:0] cwv=0; reg signed [511:0] cbv=0,cmv=0; reg [95:0] csv=0;
  reg djv=0; wire djr; reg dsb=0; reg [3:0] dse=0; reg [23:0] dba=0; reg [15:0] dsm=16'hffff; reg [1:0] dss=1; reg [7:0] dfh=10,dfw=10,dfp=10; reg dtb=0; reg [3:0] dte=0; reg [7:0] dtt=8'h22; reg [2:0] dcg=0; reg [3:0] dgc=1; reg [7:0] dpc=64; reg [31:0] dzp=0,dmin=-2147483648,dmax=2147483647; wire ddv; reg ddr=1; wire ddb; wire [3:0] dde; wire [7:0] ddt; wire [2:0] ddg;
  reg pwwv=0; reg [15:0] pwwi=0; reg signed [7:0] pwwd=1; reg pwbv=0; reg [8:0] pwbi=0; reg signed [31:0] pwbd=0; reg pwmv=0; reg [8:0] pwmi=0; reg signed [31:0] pwmd=0; reg pwsv=0;
  reg [8:0] pwsi=0; reg [5:0] pwsd=0; reg pjv=0; wire pjr; reg pjb=0; reg [3:0] pje=0; reg [7:0] pjt=8'h22; reg [7:0] pjc=16; reg [8:0] pjo=8; reg [7:0] pjp=64; reg [31:0] pz=0,pmin=-2147483648,pmax=2147483647; wire pdv; reg pdr=1; wire [7:0] ppi; wire [8:0] pco; wire signed [7:0] pdo; wire pddb; wire [1:0] s0,s1; wire [31:0] dwc,doc,prc,pic;
  ds_word_window_dw_pw_tile_pipeline #(.MAX_CIN(16),.MAX_COUT(16),.MAX_IN_H(10),.MAX_IN_W(10)) dut(.clk(clk),.rst_n(rst_n),.fill_start_valid(fsv),.fill_start_ready(fsr),.fill_start_bank(fsb),.fill_start_epoch(fse),.fill_start_base_addr(fba),.fill_start_word_count(fwc),.fill_done_valid(fdv),.fill_done_ready(1'b1),.fill_done_bank(fdb),.fill_done_epoch(fde),.mem_req_valid(mrv),.mem_req_ready(mrr),.mem_req_addr(mra),.mem_resp_valid(mspv),.mem_resp_data(msd),.cfg_valid(cv),.cfg_ready(cready),.cfg_tap_idx(cti),.cfg_weight_vec(cwv),.cfg_bias_vec(cbv),.cfg_multiplier_vec(cmv),.cfg_shift_vec(csv),.dw_job_valid(djv),.dw_job_ready(djr),.dw_source_bank(dsb),.dw_source_epoch(dse),.dw_source_base_addr(dba),.dw_source_lane_mask(dsm),.dw_source_stride(dss),.dw_footprint_height(dfh),.dw_footprint_width(dfw),.dw_footprint_pitch(dfp),.dw_target_bank(dtb),.dw_target_epoch(dte),.dw_target_tile(dtt),.dw_channel_group(dcg),.dw_group_count(dgc),.dw_pixel_count(dpc),.dw_output_zero_point(dzp),.dw_activation_min(dmin),.dw_activation_max(dmax),.dw_done_valid(ddv),.dw_done_ready(1'b1),.dw_done_bank(ddb),.dw_done_epoch(dde),.dw_done_tile(ddt),.dw_done_group(ddg),.pw_weight_wr_en(pwwv),.pw_weight_wr_idx(pwwi),.pw_weight_wr_data(pwwd),.pw_bias_wr_en(pwbv),.pw_bias_wr_idx(pwbi),.pw_bias_wr_data(pwbd),.pw_multiplier_wr_en(pwmv),.pw_multiplier_wr_idx(pwmi),.pw_multiplier_wr_data(pwmd),.pw_shift_wr_en(pwsv),.pw_shift_wr_idx(pwsi),.pw_shift_wr_data(pwsd),.pw_job_valid(pjv),.pw_job_ready(pjr),.pw_bank(pjb),.pw_epoch(pje),.pw_tile(pjt),.pw_input_channels(pjc),.pw_output_channels(pjo),.pw_pixel_count(pjp),.pw_output_zero_point(pz),.pw_activation_min(pmin),.pw_activation_max(pmax),.pw_done_valid(pddb),.pw_done_ready(1'b1),.pw_done_bank(),.pw_done_epoch(),.pw_done_tile(),.pw_out_valid(pdv),.pw_out_ready(pdr),.pw_out_pixel_idx(ppi),.pw_out_channel_idx(pco),.pw_out_data(pdo),.scratch0_state(s0),.scratch1_state(s1),.dw_write_count(dwc),.dw_overlap_cycles(doc),.pw_read_count(prc),.pw_issue_count(pic));
  integer n,errors=0,cycles=0,outs=0; reg [3:0] qv[0:3]; reg [31:0] qd[0:3];
  function integer val; input integer vec,lane; begin val=((vec%10)==0 || (vec/10)==0 || (vec%10)==9 || (vec/10)==9)?0:1; end endfunction
  function [31:0] word; input [23:0] a; integer off,v,l; begin off=a-BASE0; if(a>=BASE1) off=a-BASE1; v=off/16; word=0; for(l=0;l<4;l=l+1) word[l*8 +:8]=val(v,(off%16)+l); end endfunction
  always @(posedge clk) begin cycles<=cycles+1; if(!rst_n) begin mspv<=0;mrr<=1; for(n=0;n<4;n=n+1) begin qv[n]<=0;qd[n]<=0;end end else begin mspv<=qv[0];msd<=qd[0]; for(n=0;n<3;n=n+1) begin qv[n]<=qv[n+1];qd[n]<=qd[n+1];end qv[3]<=0; if(mrv&&mrr) begin qv[3]<=1;qd[3]<=word({mra[23:2],2'b0});end mrr<=((cycles%17)!=5); end end
  always @(negedge clk) if (rst_n) pdr <= ((cycles % 5) != 0);
  task cfg_dw; integer t,l; begin for(t=0;t<9;t=t+1) begin @(negedge clk);cti=t;cwv=0;cbv=0;cmv=0;csv=0;for(l=0;l<16;l=l+1)cwv[l*8 +:8]=1;cv=1;while(!cready)@(posedge clk);@(posedge clk);@(negedge clk);cv=0;end end endtask
  task cfg_pw; integer k,o; begin for(o=0;o<16;o=o+1) begin @(negedge clk);pwbi=o;pwbd=0;pwbv=1;@(posedge clk);@(negedge clk);pwbv=0;pwmi=o;pwmd=0;pwmv=1;@(posedge clk);@(negedge clk);pwmv=0;pwsi=o;pwsd=0;pwsv=1;@(posedge clk);@(negedge clk);pwsv=0; for(k=0;k<16;k=k+1) begin pwwi=o*16+k;pwwd=1;pwwv=1;@(posedge clk);@(negedge clk);pwwv=0;end end end endtask
  task fill; input integer bank; begin @(negedge clk);fsb=bank;fse=1;fba=bank?BASE1:BASE0;fwc=400;fsv=1;while(!fsr)@(posedge clk);@(posedge clk);@(negedge clk);fsv=0;while(!fdv)@(posedge clk); end endtask
  task dw_job; input integer bank; input integer pixels; begin @(negedge clk);dsb=bank;dse=1;dba=bank?BASE1:BASE0;dtb=bank;dte=1;dtt=8'h22;dcg=0;dgc=1;dpc=pixels;djv=1;while(!djr)@(posedge clk);@(posedge clk);@(negedge clk);djv=0;while(!ddv)@(posedge clk); end endtask
  task pw_job; input integer bank; input integer pixels; input integer cout; input integer expected; integer start_count; begin start_count=outs; @(negedge clk);pjb=bank;pje=1;pjt=8'h22;pjc=16;pjo=cout;pjp=pixels;pjv=1;while(!pjr)@(posedge clk);@(posedge clk);@(negedge clk);pjv=0;while(!pddb)begin @(posedge clk);if(pdv&&pdr)begin outs=outs+1;if(pdo!==0)errors=errors+1;if(outs-start_count<=4)$display("PWOUT %0d pix=%0d ch=%0d",outs-start_count,ppi,pco);end end if((outs-start_count)!=expected) errors=errors+1; end endtask
  initial begin fork begin #200000;$display("TIMEOUT tilepipe state dw=%0d pw=%0d row=%0d group=%0d outputs=%0d dwc=%0d prc=%0d rqbusy=%b rqv=%b owner=%b bankout=%b relready=%b",dut.dw_state,dut.pw_state,dut.pw_row_reg,dut.pw_cout_group,outs,dwc,prc,dut.rq_busy,dut.rq_valid,dut.u_scratch0.owner,dut.u_scratch0.pw_out_valid,dut.prl0_ready);$finish;end join_none repeat(3)@(posedge clk);rst_n=1;cfg_dw;cfg_pw;fill(0);dw_job(0,64);pw_job(0,64,8,512);fill(0);dw_job(0,17);pw_job(0,17,13,221);fill(1);dw_job(1,64);pw_job(1,64,8,512);if(errors==0)$display("PASS tb_ds_word_window_dw_pw_tile_pipeline outputs=%0d dw_writes=%0d pw_reads=%0d overlap=%0d cycles=%0d",outs,dwc,prc,doc,cycles);else $display("FAIL tb_ds_word_window_dw_pw_tile_pipeline errors=%0d outputs=%0d",errors,outs);$finish;end
endmodule
